#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 64
#define NIL -1

static long value[MAX_NODES];
static int left[MAX_NODES];
static int right[MAX_NODES];
static int root = NIL;
static int used = 0;
static int printed = 0;

static void print_value(long v) {
    if (printed) putchar(' ');
    printf("%ld", v);
    printed = 1;
}

static void bst_insert(long v) {
    if (used >= MAX_NODES) return;
    if (root == NIL) {
        root = used;
        value[used] = v;
        left[used] = right[used] = NIL;
        ++used;
        return;
    }
    int cur = root;
    while (1) {
        if (v < value[cur]) {
            if (left[cur] == NIL) {
                left[cur] = used;
                value[used] = v;
                left[used] = right[used] = NIL;
                ++used;
                return;
            }
            cur = left[cur];
        } else if (v > value[cur]) {
            if (right[cur] == NIL) {
                right[cur] = used;
                value[used] = v;
                left[used] = right[used] = NIL;
                ++used;
                return;
            }
            cur = right[cur];
        } else {
            return; // duplicate
        }
    }
}

static void inorder(int node) {
    if (node == NIL) return;
    inorder(left[node]);
    print_value(value[node]);
    inorder(right[node]);
}

static void preorder(int node) {
    if (node == NIL) return;
    print_value(value[node]);
    preorder(left[node]);
    preorder(right[node]);
}

static void postorder(int node) {
    if (node == NIL) return;
    postorder(left[node]);
    postorder(right[node]);
    print_value(value[node]);
}

int main(int argc, char *argv[]) {
    if (argc < 2) { puts("INVALID_MODE"); return 0; }
    const char *mode = argv[1];
    if (strcmp(mode, "in") && strcmp(mode, "pre") && strcmp(mode, "post")) {
        puts("INVALID_MODE");
        return 0;
    }
    for (int i = 2; i < argc && used < MAX_NODES; ++i) {
        char *end;
        long v = strtol(argv[i], &end, 10);
        if (*end == '\0') bst_insert(v);
    }
    if (root == NIL) { puts("EMPTY"); return 0; }
    printed = 0;
    if (!strcmp(mode, "in")) inorder(root);
    else if (!strcmp(mode, "pre")) preorder(root);
    else postorder(root);
    putchar('\n');
    return 0;
}
